// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient, uint256 seedAmount) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        uint256 amount = bound(seedAmount, 0, 1 ether);

        vm.deal(caller, amount + 1 wei);

        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        bool property = false;
        if (ok) {
            property = (caller == address(this)) && (address(c).balance == 0);
        } else {
            property = (caller != address(this)) && (address(c).balance == amount);
        }

        assertTrue(property);
    }
}
